        rows.append("td").attr("class", "col-name").text((d) => d.fullName);
        rows.append("td").attr("class", "col-sector")
            .html((d) => {
                const color = SECTOR_COLORS[d.sector] || "#999";
                return '<span class="sector-pill" style="background:' + color + ';">' +
                    d.sector + "</span>";
